1	// Package review — see env.go for package-level rationale.
2	//
3	// scope.go implements scope detection for `entire review`. The scope is the
4	// git ref the review is bounded by: "commits unique to this branch vs
5	// <baseRef>". Pinning the scope at launch time prevents the divergent-default
6	// problem where different agents default to different comparison points (e.g.
7	// codex used origin/main...HEAD, claude used working-tree-only) on the same
8	// invocation.
9	package review
10	
11	import (
12		"context"
13		"errors"
14		"fmt"
15		"os/exec"
16		"strconv"
17		"strings"
18		"time"
19	
20		"github.com/go-git/go-git/v6"
21		"github.com/go-git/go-git/v6/plumbing"
22		"github.com/go-git/go-git/v6/plumbing/object"
23		"github.com/go-git/go-git/v6/plumbing/storer"
24	)
25	
26	// ScopeStats summarises the scope of a review for the banner.
27	type ScopeStats struct {
28		BaseRef       string
29		CurrentBranch string // empty for detached HEAD
30		Commits       int    // commits unique to current branch vs BaseRef
31		FilesChanged  int    // files changed across those commits
32		Uncommitted   int    // uncommitted file changes in the working tree
33	}
34	
35	// formatScopeBanner produces the line printed before agent launch:
36	//
37	//	"Reviewing feat/X vs main: 3 commits, 7 files changed, 2 uncommitted"
38	//
39	// Pluralisation: "1 commit" / "2 commits", "1 file" / "N files",
40	// always "uncommitted" (a count, not a noun phrase).
41	func formatScopeBanner(stats ScopeStats) string {
42		subject := stats.CurrentBranch
43		if subject == "" {
44			subject = "detached HEAD"
45		}
46	
47		commitWord := "commits"
48		if stats.Commits == 1 {
49			commitWord = "commit"
50		}
51		fileWord := "files"
52		if stats.FilesChanged == 1 {
53			fileWord = "file"
54		}
55	
56		return fmt.Sprintf(
57			"Reviewing %s vs %s: %d %s, %d %s changed, %d uncommitted",
58			subject,
59			stats.BaseRef,
60			stats.Commits,
61			commitWord,
62			stats.FilesChanged,
63			fileWord,
64			stats.Uncommitted,
65		)
66	}
67	
68	// ComputeScopeStats gathers the data formatScopeBanner needs.
69	// Used by CU6 to build the banner before launching agents.
70	func ComputeScopeStats(ctx context.Context, repo *git.Repository) (ScopeStats, error) {
71		baseRef, err := detectScopeBaseRef(ctx, repo)
72		if err != nil {
73			return ScopeStats{}, fmt.Errorf("detect scope base ref: %w", err)
74		}
75	
76		repoRoot, err := repoWorktreePath(repo)
77		if err != nil {
78			return ScopeStats{}, fmt.Errorf("get repo root: %w", err)
79		}
80	
81		currentBranch := currentBranchName(repo)
82	
83		commits, err := countCommits(ctx, repoRoot, baseRef)
84		if err != nil {
85			return ScopeStats{}, fmt.Errorf("count commits: %w", err)
86		}
87	
88		filesChanged, err := countFilesChanged(ctx, repoRoot, baseRef)
89		if err != nil {
90			return ScopeStats{}, fmt.Errorf("count files changed: %w", err)
91		}
92	
93		uncommitted, err := countUncommitted(ctx, repoRoot)
94		if err != nil {
95			return ScopeStats{}, fmt.Errorf("count uncommitted: %w", err)
96		}
97	
98		return ScopeStats{
99			BaseRef:       baseRef,
100			CurrentBranch: currentBranch,
101			Commits:       commits,
102			FilesChanged:  filesChanged,
103			Uncommitted:   uncommitted,
104		}, nil
105	}
106	
107	// detectScopeBaseRef finds the closest non-self ancestor branch the
108	// review should be scoped against. Strategy:
109	//
110	//  1. Find local + remote branches whose tips are ancestors of HEAD
111	//     (i.e., branches the current branch is descended from). Exclude
112	//     the current branch itself.
113	//  2. Pick the one with the most recent commit timestamp at its tip.
114	//     This handles stacked PRs where a feature branches off another
115	//     feature: prefer the immediate parent over a more distant one.
116	//  3. Fallback chain when no ancestor is found:
117	//     origin/HEAD → origin/main → origin/master → main → master
118	//  4. If none of those exist either, return an error.
119	//
120	// Returns the ref name (e.g., "main", "origin/main", "feat/parent")
121	// suitable for use in `git diff <ref>...HEAD`.
122	func detectScopeBaseRef(ctx context.Context, repo *git.Repository) (string, error) {
123		head, err := repo.Head()
124		if err != nil {
125			return fallbackScopeRef(repo)
126		}
127		headHash := head.Hash()
128	
129		// Determine the current branch's symbolic ref name (empty for detached HEAD).
130		currentBranchShort := ""
131		if head.Name().IsBranch() {
132			currentBranchShort = head.Name().Short() // e.g. "feat/x"
133		}
134	
135		repoRoot, rootErr := repoWorktreePath(repo)
136		if rootErr != nil {
137			return fallbackScopeRef(repo)
138		}
139	
140		// Enumerate ancestor branches in a single git invocation. for-each-ref
141		// --merged HEAD lets git use its commit-graph index to answer "is this
142		// ref an ancestor of HEAD?" in O(1) per ref via packed reachability
143		// rather than the previous O(branches × commits) repo.Log walks.
144		type candidate struct {
145			name    string
146			tipUnix int64
147		}
148		var candidates []candidate
149	
150		out, runErr := runGit(ctx, repoRoot,
151			"for-each-ref",
152			"--merged", "HEAD",
153			"--format=%(refname:short)%09%(committerdate:unix)",
154			"refs/heads/", "refs/remotes/",
155		)
156		if runErr != nil {
157			// git for-each-ref unavailable or repo state confused — fall back
158			// to a slow walk via go-git, mirroring the prior behaviour rather
159			// than failing the review launch.
160			return slowDetectScopeBaseRef(ctx, repo, headHash, currentBranchShort)
161		}
162	
163		for _, line := range strings.Split(out, "\n") {
164			if ctx.Err() != nil {
165				return "", ctx.Err() //nolint:wrapcheck // propagate context cancellation
166			}
167			line = strings.TrimSpace(line)
168			if line == "" {
169				continue
170			}
171			parts := strings.SplitN(line, "\t", 2)
172			if len(parts) != 2 {
173				continue
174			}
175			name := parts[0]
176			// Skip the current branch itself (and its full ref form, both shapes
177			// for-each-ref might emit).
178			if name == currentBranchShort {
179				continue
180			}
181			// Skip refs that resolve to the same commit as HEAD — same hash,
182			// different name (e.g. an unmoved freshly-merged feature).
183			if hash, lookupErr := repo.ResolveRevision(plumbing.Revision(name)); lookupErr == nil && hash != nil && *hash == headHash {
184				continue
185			}
186			unix, parseErr := strconv.ParseInt(parts[1], 10, 64)
187			if parseErr != nil {
188				continue
189			}
190			candidates = append(candidates, candidate{name: name, tipUnix: unix})
191		}
192	
193		if len(candidates) > 0 {
194			// Pick the candidate with the most recent tip (closest ancestor).
195			best := candidates[0]
196			for _, c := range candidates[1:] {
197				if c.tipUnix > best.tipUnix {
198					best = c
199				}
200			}
201			return best.name, nil
202		}
203	
204		return fallbackScopeRef(repo)
205	}
206	
207	// slowDetectScopeBaseRef is the pre-optimization fallback used only when the
208	// `git for-each-ref --merged` shell-out fails. It walks all refs and checks
209	// ancestry via repo.Log per ref (O(branches × commits)). Kept as a defense
210	// against environments where git CLI is unavailable but go-git can still
211	// resolve refs.
212	func slowDetectScopeBaseRef(ctx context.Context, repo *git.Repository, headHash plumbing.Hash, currentBranchShort string) (string, error) {
213		refs, err := repo.References()
214		if err != nil {
215			return fallbackScopeRef(repo)
216		}
217	
218		type candidate struct {
219			name    string
220			tipTime time.Time
221		}
222		var candidates []candidate
223	
224		_ = refs.ForEach(func(ref *plumbing.Reference) error { //nolint:errcheck // best-effort search
225			if ctx.Err() != nil {
226				return ctx.Err()
227			}
228			if !ref.Name().IsBranch() && !ref.Name().IsRemote() {
229				return nil
230			}
231			if ref.Name().Short() == currentBranchShort {
232				return nil
233			}
234			tipHash := ref.Hash()
235			if tipHash == headHash {
236				return nil
237			}
238			isAnc, ancErr := isAncestorOf(ctx, repo, tipHash, headHash)
239			if ancErr != nil {
240				return nil //nolint:nilerr // best-effort: skip unresolvable refs
241			}
242			if !isAnc {
243				return nil
244			}
245			commit, cErr := repo.CommitObject(tipHash)
246			if cErr != nil {
247				return nil //nolint:nilerr // best-effort: skip refs with no commit object
248			}
249			candidates = append(candidates, candidate{
250				name:    ref.Name().Short(),
251				tipTime: commit.Committer.When,
252			})
253			return nil
254		})
255		if ctx.Err() != nil {
256			return "", ctx.Err() //nolint:wrapcheck // propagate context cancellation
257		}
258		if len(candidates) > 0 {
259			best := candidates[0]
260			for _, c := range candidates[1:] {
261				if c.tipTime.After(best.tipTime) {
262					best = c
263				}
264			}
265			return best.name, nil
266		}
267		return fallbackScopeRef(repo)
268	}
269	
270	// repoWorktreePath returns the working-tree path for repo, or an error if the
271	// repo is bare or its worktree can't be resolved. detectScopeBaseRef needs
272	// this to invoke `git for-each-ref` with the right working directory.
273	func repoWorktreePath(repo *git.Repository) (string, error) {
274		wt, err := repo.Worktree()
275		if err != nil {
276			return "", fmt.Errorf("resolve worktree: %w", err)
277		}
278		return wt.Filesystem().Root(), nil
279	}
280	
281	// fallbackScopeRef returns the first existing ref from the fallback chain:
282	// origin/HEAD → origin/main → origin/master → main → master.
283	// Returns an error if none exist.
284	func fallbackScopeRef(repo *git.Repository) (string, error) {
285		chain := []string{"origin/HEAD", "origin/main", "origin/master", "main", "master"}
286		for _, name := range chain {
287			if refExists(repo, name) {
288				return name, nil
289			}
290		}
291		return "", errors.New("no suitable ancestor branch found; configure a base ref explicitly")
292	}
293	
294	// refExists reports whether a ref with the given short name exists in repo.
295	func refExists(repo *git.Repository, shortName string) bool {
296		refs, err := repo.References()
297		if err != nil {
298			return false
299		}
300		found := false
301		_ = refs.ForEach(func(ref *plumbing.Reference) error { //nolint:errcheck // best-effort search
302			if ref.Name().Short() == shortName {
303				found = true
304				return storer.ErrStop
305			}
306			return nil
307		})
308		return found
309	}
310	
311	// isAncestorOf checks if candidate is an ancestor of (or equal to) target
312	// by walking the commit graph from target backwards.
313	func isAncestorOf(ctx context.Context, repo *git.Repository, candidate, target plumbing.Hash) (bool, error) {
314		if candidate == target {
315			return true, nil
316		}
317	
318		iter, err := repo.Log(&git.LogOptions{From: target})
319		if err != nil {
320			return false, fmt.Errorf("log from target: %w", err)
321		}
322		defer iter.Close()
323	
324		found := false
325		_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // storer.ErrStop is expected
326			if ctx.Err() != nil {
327				return ctx.Err()
328			}
329			if c.Hash == candidate {
330				found = true
331				return storer.ErrStop
332			}
333			return nil
334		})
335		// Context cancellation: surface. storer.ErrStop or log exhaustion: ignore.
336		if ctx.Err() != nil {
337			return false, ctx.Err() //nolint:wrapcheck // propagate context cancellation
338		}
339		return found, nil
340	}
341	
342	// currentBranchName returns the short branch name for the current HEAD,
343	// or "" for detached HEAD.
344	func currentBranchName(repo *git.Repository) string {
345		head, err := repo.Head()
346		if err != nil {
347			return ""
348		}
349		if !head.Name().IsBranch() {
350			return "" // detached HEAD
351		}
352		return head.Name().Short()
353	}
354	
355	// countCommits returns the number of commits in <baseRef>..HEAD
356	// (commits on the current branch not in baseRef).
357	func countCommits(ctx context.Context, repoRoot, baseRef string) (int, error) {
358		out, err := runGit(ctx, repoRoot, "rev-list", "--count", baseRef+"..HEAD")
359		if err != nil {
360			return 0, err
361		}
362		n, err := strconv.Atoi(strings.TrimSpace(out))
363		if err != nil {
364			return 0, fmt.Errorf("parse commit count: %w", err)
365		}
366		return n, nil
367	}
368	
369	// countFilesChanged returns the number of unique files changed in <baseRef>..HEAD.
370	func countFilesChanged(ctx context.Context, repoRoot, baseRef string) (int, error) {
371		out, err := runGit(ctx, repoRoot, "diff", "--name-only", baseRef+"..HEAD")
372		if err != nil {
373			return 0, err
374		}
375		trimmed := strings.TrimSpace(out)
376		if trimmed == "" {
377			return 0, nil
378		}
379		return len(strings.Split(trimmed, "\n")), nil
380	}
381	
382	// countUncommitted returns the number of lines in `git status --porcelain`
383	// (each line corresponds to one changed or untracked file).
384	func countUncommitted(ctx context.Context, repoRoot string) (int, error) {
385		out, err := runGit(ctx, repoRoot, "status", "--porcelain")
386		if err != nil {
387			return 0, err
388		}
389		trimmed := strings.TrimSpace(out)
390		if trimmed == "" {
391			return 0, nil
392		}
393		return len(strings.Split(trimmed, "\n")), nil
394	}
395	
396	// runGit runs `git <args>` in repoDir and returns stdout as a string.
397	// stderr is captured separately and surfaced in the error wrap on non-zero
398	// exit. Stdout and stderr are NOT combined — git emits warnings on stderr
399	// even on successful commands (shallow-clone notices, safe.directory
400	// advisories, etc.) and merging them would corrupt parsed output (e.g.,
401	// strconv.Atoi on the result of `rev-list --count` would fail).
402	func runGit(ctx context.Context, repoRoot string, args ...string) (string, error) {
403		cmd := exec.CommandContext(ctx, "git", args...)
404		cmd.Dir = repoRoot
405		var stderr strings.Builder
406		cmd.Stderr = &stderr
407		out, err := cmd.Output()
408		if err != nil {
409			// Surface stderr so callers see why git rejected the command,
410			// not just "exit status 128".
411			stderrTxt := strings.TrimSpace(stderr.String())
412			if stderrTxt != "" {
413				return "", fmt.Errorf("git %s: %w (stderr: %s)", args[0], err, stderrTxt)
414			}
415			return "", fmt.Errorf("git %s: %w", args[0], err)
416		}
417		return string(out), nil
418	}
