			found = true
			return storer.ErrStop
		}
		return nil
	})
	// Context cancellation: surface. storer.ErrStop or log exhaustion: ignore.
	if ctx.Err() != nil {
		return false, ctx.Err() //nolint:wrapcheck // propagate context cancellation
	}
	return found, nil
}

