// produces an error before any agents are spawned, so users learn about
// the typo immediately instead of after a 10-minute review run scoped
// against a default the flag was supposed to override.
func ComputeScopeStats(ctx context.Context, repo *git.Repository, baseOverride string) (ScopeStats, error) {
	repoRoot, err := repoWorktreePath(repo)
	if err != nil {
		return ScopeStats{}, fmt.Errorf("get repo root: %w", err)
	}

	var baseRef string
	if baseOverride != "" {
		if _, vErr := runGit(ctx, repoRoot, "rev-parse", "--verify", baseOverride+"^{commit}"); vErr != nil {
