// TestComputeScopeStats_DoesNotCountUpstreamOnlyFilesAfterBaseAdvances
// guards against a subtle two-dot-vs-three-dot bug: `git diff base..HEAD`
// shows the tree diff between base and HEAD, which means files changed in
// base AFTER the branch point appear as reversed changes in the diff,
// inflating the FilesChanged count. The fix is to use three-dot syntax
// (`git diff base...HEAD`) which compares the merge-base to HEAD,
// excluding upstream-only changes.
//
// Scenario: feat/x branches off main, adds feature.go. Then main advances
// with an independent unrelated.go. The branch's "scope vs main" should
// be 1 file (feature.go), not 2 (feature.go added + unrelated.go reversed).
func TestComputeScopeStats_DoesNotCountUpstreamOnlyFilesAfterBaseAdvances(t *testing.T) {
	dir := t.TempDir()
	initRepoOnMain(t, dir)

	// main: root commit.
	commitFile(t, dir, "root.go", "package main", "init")

	// feat/x: branch off main, add feature.go.
	testutil.GitCheckoutNewBranch(t, dir, "feat/x")
	commitFile(t, dir, "feature.go", "package main", "add feature")

	// Switch back to main and advance it with an independent file.
	//nolint:noctx // test helper
	checkout := exec.Command("git", "checkout", defaultBranchName)
	checkout.Dir = dir
	if out, err := checkout.CombinedOutput(); err != nil {
		t.Fatalf("checkout %s: %v\n%s", defaultBranchName, err, out)
	}
	commitFile(t, dir, "unrelated.go", "package main", "main advances after branch point")

	// Back to feat/x for the actual review scope check.
	//nolint:noctx // test helper
	checkout = exec.Command("git", "checkout", "feat/x")
	checkout.Dir = dir
	if out, err := checkout.CombinedOutput(); err != nil {
		t.Fatalf("checkout feat/x: %v\n%s", err, out)
	}

	ctx := context.Background()
	repo := openTestRepo(t, dir)

	stats, err := ComputeScopeStats(ctx, repo, "")
	if err != nil {
		t.Fatalf("ComputeScopeStats: %v", err)
	}

	// Scope: feat/x...main. Only feature.go is unique to feat/x since the
	// branch point — unrelated.go landed on main AFTER the branch was cut
	// and is not part of feat/x's contribution.
	if stats.FilesChanged != 1 {
		t.Errorf("FilesChanged = %d, want 1 (only feature.go is unique to feat/x; unrelated.go is upstream-only and must not be counted)", stats.FilesChanged)
	}
}

