// wrapDisplayWidth wraps s to a slice of display lines, each fitting within
// the given width in terminal cells. Mirrors truncateDisplayWidth's
// width-aware design but produces multiple lines instead of truncating.
// Preserves embedded newlines as paragraph boundaries.
//
// width <= 0 returns the input as a single-element slice (no-op).
func wrapDisplayWidth(s string, width int) []string {
    if width <= 0 {
        return []string{s}
    }
    wrapped := ansi.Wrap(s, width, "")
    if wrapped == "" {
        return []string{""}
    }
    return strings.Split(wrapped, "\n")
}
```

