// eventLines converts a single Event to display lines, wrapped to maxWidth.
// Most event types produce a single line (Started, Finished, Tokens — short
// labels). AssistantText and long ToolCall args may produce multiple wrapped
// lines. The list is then joined with "\n" by callers.
func eventLines(ev reviewtypes.Event, maxWidth int) []string {
    var raw string
    switch e := ev.(type) {
    case reviewtypes.Started:
        raw = "[started]"
    case reviewtypes.AssistantText:
        raw = e.Text
    case reviewtypes.ToolCall:
        raw = fmt.Sprintf("[tool: %s] %s", e.Name, e.Args)
    case reviewtypes.Tokens:
        raw = fmt.Sprintf("[tokens in=%d out=%d]", e.In, e.Out)
    case reviewtypes.Finished:
        if e.Success {
            raw = "[finished: success]"
        } else {
            raw = "[finished: failed]"
        }
    case reviewtypes.RunError:
        if e.Err != nil {
            raw = fmt.Sprintf("[error: %v]", e.Err)
        } else {
            raw = "[error]"
        }
    default:
        raw = "[unknown event]"
    }
    return wrapDisplayWidth(sanitizeDisplayText(raw), maxWidth)
}
```

