// refreshDetailContent regenerates the detail-mode viewport content from
// the focused agent's event buffer and sets it on the viewport. Preserves
// scroll position when the user is not at the bottom (no auto-tail); jumps
// to bottom when the user was already there (auto-tail).
func (m *reviewTUIModel) refreshDetailContent() {
    if !m.detailMode || len(m.rows) == 0 || m.detailIdx >= len(m.rows) {
        return
    }
    wasAtBottom := m.detail.AtBottom()

    row := m.rows[m.detailIdx]
    width := m.detail.Width
    if width <= 0 {
        width = 80
    }
    var lines []string
    for _, ev := range row.buffer {
        lines = append(lines, eventLines(ev, width)...)
    }
    m.detail.SetContent(strings.Join(lines, "\n"))

    if wasAtBottom {
        m.detail.GotoBottom()
    }
}
```

