// detailFrame renders the alt-screen drill-in frame for one agent: header,
// pre-rendered viewport body, and footer, padded to exactly termHeight lines.
// The body comes from the viewport.Model.View() so scroll/wrap is handled
// by the widget.
func detailFrame(row agentRow, viewportBody string, termWidth, termHeight int) string {
    if termWidth < 1 {
        termWidth = 80
    }
    if termHeight < 3 {
        termHeight = 3
    }
    headerContent := fmt.Sprintf("─── %s (%d events) ", sanitizeDisplayText(row.name), len(row.buffer))
    header := padDisplayWidthWith(headerContent, termWidth, "─")
    footer := padDisplayWidth("←/→ switch agent · Esc back · ↑/↓/PgUp/PgDn scroll", termWidth)

    var b strings.Builder
    b.WriteString(header)
    b.WriteString("\n")
    b.WriteString(viewportBody)
    b.WriteString("\n")
    b.WriteString(footer)
    return b.String()
}
```

