func TestWrapDisplayWidth_ShortLineUnwrapped(t *testing.T) {
	t.Parallel()
	got := wrapDisplayWidth("hello world", 40)
	if len(got) != 1 || got[0] != "hello world" {
		t.Errorf("got %#v, want [hello world]", got)
	}
}

func TestWrapDisplayWidth_LongLineWrapsAtWord(t *testing.T) {
	t.Parallel()
	got := wrapDisplayWidth("the quick brown fox jumps over the lazy dog", 12)
	if len(got) < 2 {
		t.Fatalf("expected wrap to multiple lines, got %#v", got)
	}
	for _, line := range got {
		if w := ansi.StringWidth(line); w > 12 {
			t.Errorf("line %q width %d exceeds max 12", line, w)
		}
	}
}

// TestWrapDisplayWidth_PreservesEmbeddedNewlines is load-bearing for the
// drill-in viewport: AssistantText events frequently contain multi-paragraph
// agent output, and collapsing those paragraphs into a single line would
// destroy the structure the user wants to read.
func TestWrapDisplayWidth_PreservesEmbeddedNewlines(t *testing.T) {
	t.Parallel()
	got := wrapDisplayWidth("first paragraph\nsecond paragraph", 40)
	if len(got) != 2 {
		t.Errorf("expected 2 lines (one per paragraph), got %#v", got)
	}
	if got[0] != "first paragraph" {
		t.Errorf("got[0] = %q, want %q", got[0], "first paragraph")
	}
	if got[1] != "second paragraph" {
		t.Errorf("got[1] = %q, want %q", got[1], "second paragraph")
	}
}

func TestWrapDisplayWidth_ZeroOrNegativeWidthReturnsInput(t *testing.T) {
	t.Parallel()
	got := wrapDisplayWidth("anything", 0)
	if len(got) != 1 || got[0] != "anything" {
		t.Errorf("expected passthrough on width<=0; got %#v", got)
	}
	got = wrapDisplayWidth("anything", -1)
	if len(got) != 1 || got[0] != "anything" {
		t.Errorf("expected passthrough on negative width; got %#v", got)
	}
}

func TestWrapDisplayWidth_EmptyInput(t *testing.T) {
	t.Parallel()
	got := wrapDisplayWidth("", 40)
	if len(got) != 1 || got[0] != "" {
		t.Errorf("expected single empty line for empty input, got %#v", got)
	}
}

