92	func TestGeminiReviewer_NoBinaryRequiredAtConstruction(t *testing.T) {
93		// No t.Parallel — uses t.Setenv.
94		t.Setenv("PATH", "")
95	
96		r := NewReviewer()
97		cfg := reviewtypes.RunConfig{
98			Skills:      []string{"/test"},
99			StartingSHA: "abc123",
100		}
101	
102		ctx, cancel := context.WithCancel(context.Background())
103		defer cancel()
104	
105		// Construction (NewReviewer) MUST NOT touch PATH. Start may or may
106		// not error depending on whether the OS-level cmd.Start tries to
107		// resolve before fork — that's fine. The contract is just "no panic
108		// and no upfront LookPath call".
109		proc, err := r.Start(ctx, cfg)
110		// Either Start succeeded (deferred lookup; binary error surfaces in Wait)
111		// or Start failed with exec.ErrNotFound (immediate lookup at Cmd.Start).
112		// Both satisfy the deferred-lookup contract — what we explicitly DON'T
113		// want is a panic or error from NewReviewer itself.
114		if err != nil && !errors.Is(err, exec.ErrNotFound) {
115			// Tolerate "no such file" wrapping variations
116			if !strings.Contains(err.Error(), "executable file not found") &&
117				!strings.Contains(err.Error(), "no such file") {
118				t.Errorf("unexpected error type: %v", err)
119			}
120		}
121		if proc != nil {
122			// Drain events to let parser goroutine exit cleanly.
123			drainGeminiEvents(proc.Events())
124			_ = proc.Wait() //nolint:errcheck // best-effort cleanup in test
125		}
126	}
