129		t.Parallel()
130		// Trigger bufio.Scanner's "token too long" error: produce a "line"
131		// that exceeds the 16MB max buffer without containing a newline.
132		r, w := io.Pipe()
133		go func() {
134			defer w.Close()
135			// 17MB of contiguous bytes without a newline
136			buf := make([]byte, 1024*1024)
