148		fin, ok := last.(reviewtypes.Finished)
149		if !ok {
150			t.Fatalf("last event must be Finished, got %T", last)
151		}
152		if fin.Success {
153			t.Error("Finished.Success must be false on scanner error")
154		}
155		// Also assert at least one RunError event was emitted before Finished.
156		sawRunError := false
157		for _, ev := range events {
158			if _, ok := ev.(reviewtypes.RunError); ok {
159				sawRunError = true
160				break
161			}
162		}
