// explainEmptyManifest returns a single-line diagnostic explaining why
// matchReviewSessionState produced no matches for any agent run in summary,
// plus a sentinel flag indicating the function fell through every known
// rejection cause. The sentinel means matcher and explainer drifted and
// callers should escalate logging.
//
// Filter precedence mirrors matchReviewSessionState: worktree path,
// BaseCommit, StartedAt window, then AgentType. Filters are applied
// cumulatively to the candidate set: the function reports the filter that
// empties the set, so heterogeneous failures across multiple tagged states
// (e.g. one wrong-worktree, one right-worktree but wrong-SHA) are diagnosed
// against the filter that actually eliminated the last surviving candidate
// rather than the first filter to find any non-matching state. AgentType is
// checked per-agent so a multi-agent run with heterogeneous type mismatches
// names the specific failing agent rather than blaming the first one in
// the run list.
func explainEmptyManifest(
	worktreeRoot string,
	headSHA string,
	summary reviewtypes.RunSummary,
	states []*session.State,
) (reason string, sentinel bool) {
	if len(states) == 0 {
		return "no session states found (lifecycle hook never created session state for any agent in this run)", false
	}
	tagged := make([]*session.State, 0, len(states))
	for _, st := range states {
		if st != nil && st.Kind == session.KindAgentReview {
			tagged = append(tagged, st)
		}
	}
	if len(tagged) == 0 {
		return fmt.Sprintf("found %d session state(s) but none tagged as a review session (env-var handshake did not reach the hook)", len(states)), false
	}

	candidates := tagged

	// Worktree filter: cumulative.
	survivors, droppedExample := applyFilter(candidates, func(st *session.State) bool {
		return worktreeRoot == "" || st.WorktreePath == "" || st.WorktreePath == worktreeRoot
	})
	if len(survivors) == 0 {
		return fmt.Sprintf("found %d tagged review session(s) but worktree path mismatch: state=%q, run=%q", len(tagged), droppedExample.WorktreePath, worktreeRoot), false
	}
	candidates = survivors

	// BaseCommit filter: cumulative.
	survivors, droppedExample = applyFilter(candidates, func(st *session.State) bool {
		return headSHA == "" || st.BaseCommit == "" || st.BaseCommit == headSHA
	})
	if len(survivors) == 0 {
		return fmt.Sprintf("found %d tagged review session(s) but BaseCommit mismatch: state=%q, run=%q (HEAD moved between review start and first agent turn?)", len(tagged), droppedExample.BaseCommit, headSHA), false
	}
	candidates = survivors

	// StartedAt window filter: cumulative.
	survivors, _ = applyFilter(candidates, func(st *session.State) bool {
		return summary.StartedAt.IsZero() || !st.StartedAt.Before(summary.StartedAt.Add(-5*time.Second))
	})
	if len(survivors) == 0 {
		return fmt.Sprintf("found %d tagged review session(s) but they started before the review run window (stale session state from a prior run?)", len(tagged)), false
	}
	candidates = survivors

	// AgentType filter: per-agent. Each run's wantType is checked against
	// the remaining candidates; if no candidate's AgentType matches, that
	// specific agent is named. Lenient cases (state.AgentType=="" or
	// wantType=="") count as a match, matching the matcher's behavior.
	for _, run := range summary.AgentRuns {
		wantType := agentTypeForReviewAgent(run.Name)
		if wantType == "" {
			continue
		}
		var observedType string
		anyMatch := false
		for _, st := range candidates {
			if st.AgentType == "" || st.AgentType == wantType {
				anyMatch = true
				break
			}
			observedType = string(st.AgentType)
		}
		if !anyMatch {
			return fmt.Sprintf("found %d tagged review session(s) but AgentType mismatch for agent %q: state=%q, run=%q", len(tagged), run.Name, observedType, wantType), false
		}
	}

	return fmt.Sprintf("found %d tagged review session(s) but matcher rejected all of them (no filter explained the rejection — please report this as a bug)", len(tagged)), true
}

// applyFilter returns the subset of candidates for which keep returns true,
// plus a pointer to the first dropped state (or nil if none were dropped).
// The dropped example is used to populate observed-vs-expected values in
// the diagnostic when a filter empties the candidate set.
func applyFilter(candidates []*session.State, keep func(*session.State) bool) (survivors []*session.State, droppedExample *session.State) {
	for _, st := range candidates {
		if keep(st) {
			survivors = append(survivors, st)
			continue
		}
		if droppedExample == nil {
			droppedExample = st
		}
	}
	return survivors, droppedExample
}

// TestExplainEmptyManifest_CumulativeFiltering locks the cumulative-filter
// behavior: when one tagged state fails worktree but another passes worktree
// yet fails SHA, the reported cause must be SHA (the filter that emptied
// the candidate set), not worktree (the filter that found *some* mismatched
// state but left a survivor). Without this, the diagnostic would mislead
// users by reporting whichever filter happens to be checked first.
func TestExplainEmptyManifest_CumulativeFiltering(t *testing.T) {
	t.Parallel()
	started := time.Now()
	summary := reviewtypes.RunSummary{
		StartedAt: started,
		AgentRuns: []reviewtypes.AgentRun{{Name: "claude-code"}},
	}
	// state-A: wrong worktree, right SHA. Eliminated by worktree filter.
	// state-B: right worktree, wrong SHA. Survives worktree, eliminated by SHA.
	// Both fail, so the manifest is empty. Reported cause should be SHA
	// because that's the filter that emptied the set after state-A was dropped.
	states := []*session.State{
		{
			SessionID:    "state-A",
			Kind:         session.KindAgentReview,
			WorktreePath: "/other/worktree",
			BaseCommit:   "abc123",
			StartedAt:    started.Add(time.Second),
			AgentType:    agenttypes.AgentType("Claude Code"),
		},
		{
			SessionID:    "state-B",
			Kind:         session.KindAgentReview,
			WorktreePath: "/repo",
			BaseCommit:   "deadbeef",
			StartedAt:    started.Add(time.Second),
			AgentType:    agenttypes.AgentType("Claude Code"),
		},
	}
	got, sentinel := explainEmptyManifest("/repo", "abc123", summary, states)
	if !strings.Contains(got, "BaseCommit mismatch") {
		t.Errorf("reason = %q, want 'BaseCommit mismatch' (the filter that emptied the candidate set), not worktree-mismatch", got)
	}
	if !strings.Contains(got, "deadbeef") {
		t.Errorf("reason = %q, want the surviving state's wrong SHA (deadbeef) as the observed value", got)
	}
	if strings.Contains(got, "worktree") {
		t.Errorf("reason = %q, must not blame worktree when state-B survived worktree filter", got)
	}
	if sentinel {
		t.Errorf("sentinel = true, want false")
	}
}

